def filter_even(numbers: list[int]) -> list[int]:
    """
    Filters a list of integers, returning only the even numbers.
    """
    even_numbers: list[int] = []
    for number in numbers:
        if number % 2 == 0:
            even_numbers.append(number)
    return even_numbers

def main() -> None:
    test_cases: list[tuple[list[int], list[int]]] = [
        ([1, 2, 3, 4, 5], [2, 4]),
        ([7, 9, 11], []),
        ([], []),
        ([2, 4, 6], [2, 4, 6]),
        ([1, 3, 5], [])
    ]

    for input_list, expected_output in test_cases:
        actual_output: list[int] = filter_even(input_list)
        assert actual_output == expected_output, f"Input: {input_list}, Expected: {expected_output}, Got: {actual_output}"
        print(f"Test passed for input {input_list}. Output: {actual_output}")

if __name__ == "__main__":
    main()

