def simple_calculator(
    num1: int,
    operator: str,
    num2: int
) -> int | str:
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return 'Error'
        else:
            return num1 // num2
    else:
        return 'Error'

def main() -> None:
    result1: int | str = simple_calculator(10, '+', 5)
    print(f"10 + 5 = {result1}")
    result2: int | str = simple_calculator(10, '/', 2)
    print(f"10 / 2 = {result2}")
    result3: int | str = simple_calculator(10, '/', 0)
    print(f"10 / 0 = {result3}")

if __name__ == "__main__":
    main()

