import math

def is_prime(n: int) -> bool:
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i: int = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_numbers_in_range(start: int, end: int) -> list[int]:
    if not (isinstance(start, int) and isinstance(end, int)):
        raise TypeError("Start and end must be integers.")
    if start > end:
        raise ValueError("Start cannot be greater than end.")
    primes: list[int] = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

def calculate_sum_of_primes(numbers: list[int]) -> int:
    total_sum: int = 0
    for num in numbers:
        if is_prime(num):
            total_sum += num
    return total_sum

def count_primes_up_to_n(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("Input 'n' must be an integer.")
    if n < 0:
        raise ValueError("Input 'n' must be non-negative.")
    count: int = 0
    for num in range(2, n + 1):
        if is_prime(num):
            count += 1
    return count

