import re
from collections import Counter

HASHTAG_PATTERN = re.compile(r"#(\w+)")


def extract_hashtags(
    text: str,
) -> list[str]:
    """Return every hashtag in *text*, stripped of its leading '#'."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return HASHTAG_PATTERN.findall(text)


def normalize(
    tag: str,
) -> str:
    """Fold a hashtag to a canonical, case-insensitive form."""
    return tag.lower()


def unique_hashtags(
    text: str,
) -> list[str]:
    """Hashtags of *text* in order of first appearance, ignoring case."""
    seen = set()
    ordered = []
    for tag in extract_hashtags(text):
        key = normalize(tag)
        if key not in seen:
            seen.add(key)
            ordered.append(tag)
    return ordered


def count_hashtags(
    messages: list[str],
) -> dict[str, int]:
    """Count how often each normalized hashtag occurs across *messages*."""
    tally = Counter()
    for message in messages:
        tally.update(normalize(tag) for tag in extract_hashtags(message))
    return dict(tally)


def most_common(
    messages: list[str],
    limit: int,
) -> list[tuple[str, int]]:
    """The *limit* most frequent hashtags, ties broken alphabetically."""
    if limit < 1:
        raise ValueError("limit must be positive")
    counts = count_hashtags(messages)
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ranked[:limit]


def format_report(
    messages: list[str],
) -> str:
    """Build a human-readable summary of the hashtags in *messages*."""
    lines = []
    for index, message in enumerate(messages, start=1):
        tags = unique_hashtags(message)
        rendered = ", ".join(tags) if tags else "(none)"
        lines.append(f"{index}. {rendered}")
    lines.append("")
    lines.append("Top hashtags:")
    for tag, hits in most_common(messages, 3):
        lines.append(f"  #{tag} x{hits}")
    return "\n".join(lines)


def main() -> None:
    messages = [
        "This is a #test with #python.",
        "No hashtags here.",
        "#Python is great, and so is #testing my #python scripts!",
        "Rebuilding the #test suite; #ci passes again.",
    ]
    print(extract_hashtags(messages[0]))
    print(extract_hashtags(messages[1]))
    print(format_report(messages))


if __name__ == "__main__":
    main()

