def validate_count(
    n: int,
) -> int:
    """Return n as a non-negative int, rejecting bad input."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"expected an integer, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"expected a non-negative integer, got {n}")
    return n


def list_of_squares(
    n: int,
) -> list[int]:
    """Squares of 1..n inclusive; an empty list when n is 0."""
    count: int = validate_count(n)
    return [i * i for i in range(1, count + 1)]


def sum_of_squares(
    n: int,
) -> int:
    """Total of the first n squares."""
    return sum(list_of_squares(n))


def digit_widths(
    squares: list[int],
) -> list[int]:
    """Number of decimal digits of each square, used for column alignment."""
    return [len(str(square)) for square in squares]


def column_width(
    squares: list[int],
) -> int:
    """Width of the widest square, or 1 when there is nothing to print."""
    widths: list[int] = digit_widths(squares)
    if not widths:
        return 1
    return max(widths)


def format_row(
    index: int,
    square: int,
    width: int,
) -> str:
    return f"{index:>{width}} -> {square:>{width}}"


def build_table(
    n: int,
) -> list[str]:
    """One aligned "i -> i*i" line per square."""
    squares: list[int] = list_of_squares(n)
    width: int = column_width(squares)
    rows: list[str] = []
    for index, square in enumerate(squares, start=1):
        rows.append(format_row(index, square, width))
    return rows


def render_report(
    n: int,
) -> str:
    """Table plus a summary line describing the squares of 1..n."""
    rows: list[str] = build_table(n)
    total: int = sum_of_squares(n)
    header: str = f"squares of 1..{n}"
    if not rows:
        return f"{header}\n(no squares)\ntotal: {total}"
    body: str = "\n".join(rows)
    return f"{header}\n{body}\ntotal: {total}"


def main() -> None:
    for n in (0, 3, 10):
        print(render_report(n))
        print()
    print("raw list for n=5:", list_of_squares(5))


if __name__ == "__main__":
    main()

