def calculate_grade(score: int) -> str:
    """
    Calculates the letter grade based on a given numeric score.

    Args:
        score: The numeric score (0-100).

    Returns:
        The corresponding letter grade.
    """
    if 90 <= score <= 100:
        return 'A'
    elif 80 <= score < 90:
        return 'B'
    elif 70 <= score < 80:
        return 'C'
    elif 60 <= score < 70:
        return 'D'
    else:
        return 'F'

