def roman_to_int(roman_numeral: str) -> int:
    """Converts a Roman numeral string to its integer equivalent."""
    roman_map: dict[str, int] = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value: int = 0
    prev_value: int = 0

    for char_index in range(len(roman_numeral) - 1, -1, -1):
        current_char: str = roman_numeral[char_index]
        current_value: int = roman_map[current_char]

        if current_value < prev_value:
            integer_value -= current_value
        else:
            integer_value += current_value

        prev_value = current_value
    return integer_value

