def validate_sequence(
    numbers: list[int],
) -> int:
    """Check the input describes 1..N with exactly one value absent; return N."""
    if not numbers:
        raise ValueError("at least one number is required")
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("all entries must be plain integers")
    expected_n = len(numbers) + 1
    seen = set(numbers)
    if len(seen) != len(numbers):
        raise ValueError("entries must be unique")
    if min(seen) < 1 or max(seen) > expected_n:
        raise ValueError("entries must lie between 1 and %d" % expected_n)
    return expected_n


def find_missing_number(
    numbers: list[int],
) -> int:
    """Return the single number from 1..N that is absent from `numbers`."""
    n = validate_sequence(numbers)
    return n * (n + 1) // 2 - sum(numbers)


def parse_numbers(
    text: str,
) -> list[int]:
    """Turn a comma or space separated string of numbers into a list of ints."""
    return [int(token) for token in text.replace(",", " ").split()]


def restored_sequence(
    numbers: list[int],
) -> list[int]:
    """Return the full 1..N run obtained by putting the missing value back."""
    return sorted(numbers + [find_missing_number(numbers)])


def describe(
    numbers: list[int],
) -> str:
    """Build a one-line report naming the gap and the repaired sequence."""
    missing = find_missing_number(numbers)
    given = ", ".join(str(value) for value in numbers)
    restored = ", ".join(str(value) for value in restored_sequence(numbers))
    return "[%s] is missing %d -> [%s]" % (given, missing, restored)


def report_all(
    cases: list[list[int]],
) -> list[str]:
    """Describe every case, reporting failures instead of aborting the run."""
    lines = []
    for case in cases:
        try:
            lines.append(describe(case))
        except (TypeError, ValueError) as error:
            lines.append("[%r] invalid: %s" % (case, error))
    return lines


def main() -> None:
    cases = [
        [1, 2, 4, 5],
        [5, 1, 3, 2],
        parse_numbers("7 3 1 6 2 5 8 9"),
        [2],
        [1, 2, 2, 4],
    ]
    for line in report_all(cases):
        print(line)


if __name__ == "__main__":
    main()

