def _normalize_string(s: str) -> str:
    """Helper to convert string to lowercase and remove spaces."""
    return s.replace(" ", "").lower()

def is_anagram(s1: str, s2: str) -> bool:
    """
    Checks if two strings are anagrams of each other, ignoring case and spaces.
    """
    normalized_s1: str = _normalize_string(s1)
    normalized_s2: str = _normalize_string(s2)

    if len(normalized_s1) != len(normalized_s2):
        return False

    char_counts1: dict[str, int] = _get_char_counts(normalized_s1)
    char_counts2: dict[str, int] = _get_char_counts(normalized_s2)

    return char_counts1 == char_counts2

def _get_char_counts(s: str) -> dict[str, int]:
    """Helper to count character frequencies in a string."""
    counts: dict[str, int] = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    return counts

