def validate_separator(
    separator,
):
    if not isinstance(separator, str):
        raise TypeError("separator must be a str")
    return separator


def normalize_item(
    item,
):
    if isinstance(item, str):
        return item
    raise TypeError(f"expected str element, got {type(item).__name__}")


def join_elements(
    items,
    separator,
):
    sep = validate_separator(separator)
    return sep.join(normalize_item(item) for item in items)


def split_elements(
    joined,
    separator,
):
    sep = validate_separator(separator)
    if not sep:
        return list(joined)
    return joined.split(sep)


def join_rows(
    rows,
    separator,
):
    return "\n".join(join_elements(row, separator) for row in rows)


def build_csv_row(
    fields,
):
    quoted = [f'"{field}"' if "," in field else field for field in fields]
    return join_elements(quoted, ",")


def describe_join(
    items,
    separator,
):
    joined = join_elements(items, separator)
    return f"{len(items)} item(s) joined with {separator!r} -> {joined!r}"


