from math import isfinite


def validate_dimension(
    value: float,
    name: str
) -> float:
    """Ensure a dimension is a positive, finite length."""
    if not isfinite(value):
        raise ValueError(f"{name} must be finite")
    if value <= 0:
        raise ValueError(f"{name} must be positive, got {value:g}")
    return float(value)


def rectangle_area(
    width: float,
    height: float
) -> float:
    """Return the area of a rectangle with the given width and height."""
    return validate_dimension(width, "width") * validate_dimension(height, "height")


def rectangle_perimeter(
    width: float,
    height: float
) -> float:
    """Return the perimeter of a rectangle with the given width and height."""
    sides = validate_dimension(width, "width") + validate_dimension(height, "height")
    return 2.0 * sides


def describe(
    width: float,
    height: float
) -> str:
    """Build a one-line summary of a rectangle's area and perimeter."""
    area = rectangle_area(width, height)
    perimeter = rectangle_perimeter(width, height)
    return f"{width:g} x {height:g} -> area {area:.2f}, perimeter {perimeter:.2f}"


def parse_pair(
    line: str,
    lineno: int
) -> tuple[float, float]:
    """Read a 'width height' line into a pair of numbers."""
    parts = line.replace(",", " ").split()
    if len(parts) != 2:
        raise ValueError(f"line {lineno}: expected two values, got {len(parts)}")
    numbers = []
    for part in parts:
        try:
            numbers.append(float(part))
        except ValueError:
            raise ValueError(f"line {lineno}: {part!r} is not a number") from None
    return numbers[0], numbers[1]


def report(
    lines: list[str],
    title: str
) -> str:
    """Turn raw input lines into a titled report, flagging invalid entries."""
    rows = [title]
    for lineno, line in enumerate(lines, start=1):
        try:
            width, height = parse_pair(line, lineno)
            rows.append(describe(width, height))
        except ValueError as exc:
            rows.append(f"line {lineno}: {exc}" if "line" not in str(exc) else str(exc))
    return "\n".join(rows)


def main() -> None:
    print(report(["5 10", "2.5 4", "3, 3", "7 -1", "8"], "Rectangles"))


if __name__ == "__main__":
