VALID_OPERATIONS = ("push", "pop")


def validate_operation(
    operation: str,
) -> str:
    """Normalise an operation name and reject anything unsupported."""
    normalised = operation.strip().lower()
    if normalised not in VALID_OPERATIONS:
        raise ValueError(f"unknown operation: {operation!r}")
    return normalised


def simulate_stack(
    stack: list,
    operation: str,
    item: object = None,
) -> object:
    """Apply 'push' or 'pop' to *stack* in place."""
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    action = validate_operation(operation)
    if action == "push":
        stack.append(item)
        return stack
    if not stack:
        return None
    return stack.pop()


def coerce_item(
    token: str,
) -> object:
    """Turn a textual argument into an int when it looks like one."""
    try:
        return int(token)
    except ValueError:
        return token


def parse_command(
    text: str,
) -> tuple:
    """Split a command line such as 'push 3' into operation and item."""
    parts = text.split()
    if not parts:
        raise ValueError("empty command")
    action = validate_operation(parts[0])
    if action == "push":
        if len(parts) < 2:
            raise ValueError("push requires an item")
        return action, coerce_item(" ".join(parts[1:]))
    return action, None


def format_result(
    command: str,
    result: object,
    stack: list,
) -> str:
    """Render one executed command and the resulting stack."""
    shown = "None" if result is None else repr(result)
    return f"{command:<10} -> {shown:<12} stack={stack!r}"


def run_script(
    commands: list,
    stack: list,
) -> list:
    """Execute command strings against a stack, returning report lines."""
    report = []
    for command in commands:
        action, item = parse_command(command)
        outcome = simulate_stack(stack, action, item)
        report.append(format_result(command, outcome, stack))
    return report


def main() -> None:
    script = ["push 1", "push 2", "pop", "pop", "pop", "push hi"]
    for line in run_script(script, []):
        print(line)


if __name__ == "__main__":
    main()

