from typing import List


def parse_limit(
    text: str,
) -> int:
    """Convert a textual limit into a non-negative integer."""
    stripped: str = text.strip()
    if not stripped.lstrip("+").isdigit():
        raise ValueError(f"limit must be a non-negative integer, got {text!r}")
    return int(stripped)


def cubes_up_to(
    limit: int,
) -> List[int]:
    """Return the cubes of 0..limit inclusive."""
    if limit < 0:
        raise ValueError(f"limit must be non-negative, got {limit}")
    cubes_list: List[int] = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def sum_of_cubes(
    cubes: List[int],
) -> int:
    """Total of the cubes produced for a limit."""
    return sum(cubes)


def format_row_header(
    width: int,
) -> str:
    """Column titles aligned with the data rows."""
    return f"{'n':>{width}} | {'n^3':>{width * 3}}"


def format_row(
    index: int,
    cube: int,
    width: int,
) -> str:
    """Render one line of the cubes table."""
    return f"{index:>{width}} | {cube:>{width * 3}}"


def build_table(
    cubes: List[int],
) -> List[str]:
    """Build a human readable table of indices and their cubes."""
    width: int = len(str(max(len(cubes) - 1, 0)))
    header: str = format_row_header(width)
    rows: List[str] = [format_row(i, cube, width) for i, cube in enumerate(cubes)]
    return [header] + rows


def describe(
    limit: int,
) -> str:
    """One line summary for a given limit."""
    cubes: List[int] = cubes_up_to(limit)
    total: int = sum_of_cubes(cubes)
    largest: int = cubes[-1]
    return f"limit={limit}: {len(cubes)} cubes, sum={total}, largest={largest}"


def main() -> None:
    inputs: List[str] = ["3", "0", "6"]
    for raw in inputs:
        limit: int = parse_limit(raw)
        print(describe(limit))
    table: List[str] = build_table(cubes_up_to(5))
    for line in table:
        print(line)


