def parse_numbers(
    text: str,
) -> list[float]:
    cleaned = text.replace(",", " ")
    return [float(token) for token in cleaned.split()]


def validate(
    values: list[float],
    weights: list[float],
) -> None:
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("weights must not sum to zero")


def weighted_average(
    values: list[float],
    weights: list[float],
) -> float:
    validate(values, weights)
    total = sum(v * w for v, w in zip(values, weights))
    return total / sum(weights)


def normalize_weights(
    weights: list[float],
) -> list[float]:
    total = sum(weights)
    return [w / total for w in weights]


def weighted_variance(
    values: list[float],
    weights: list[float],
) -> float:
    mean = weighted_average(values, weights)
    squared = [(v - mean) ** 2 for v in values]
    return weighted_average(squared, weights)


def format_report(
    values: list[float],
    weights: list[float],
) -> str:
    shares = normalize_weights(weights)
    lines = ["value    weight   contribution"]
    for value, weight, share in zip(values, weights, shares):
        lines.append(f"{value:8.3f} {weight:8.3f} {value * share:12.3f}")
    lines.append(f"weighted average: {weighted_average(values, weights):.3f}")
    lines.append(f"weighted variance: {weighted_variance(values, weights):.3f}")
    return "\n".join(lines)


def report_all(
    datasets: list[tuple[str, str]],
) -> str:
    blocks = []
    for value_text, weight_text in datasets:
        values = parse_numbers(value_text)
        weights = parse_numbers(weight_text)
        blocks.append(format_report(values, weights))
    return "\n\n".join(blocks)


def main() -> None:
    datasets = [("10, 20, 30", "1, 2, 1"), ("5 10", "0.5 0.5")]
    print(report_all(datasets))


