import re

def parse_log_line(log_line: str) -> dict:
    """
    Parses a log line and returns a dictionary with its components.
    """
    pattern: str = r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (?P<level>[A-Z]+) - (?P<message>.*)$"
    match: re.Match | None = re.match(pattern, log_line)

    if match:
        return match.groupdict()
    else:
        return {"timestamp": None, "level": None, "message": log_line}

def process_log_file(file_path: str) -> list[dict]:
    """
    Reads a log file and parses each line.
    """
    parsed_logs: list[dict] = []
    with open(file_path, 'r') as f:
        for line in f:
            parsed_logs.append(parse_log_line(line.strip()))
    return parsed_logs

def get_error_messages(parsed_logs: list[dict]) -> list[str]:
    """
    Extracts error messages from a list of parsed log dictionaries.
    """
    errors: list[str] = []
    for log_entry in parsed_logs:
        if log_entry.get('level') == 'ERROR':
            message: str = log_entry.get('message', 'No message')
            errors.append(message)
    return errors

def main() -> None:
