import re

def parse_log_line(log_line):
    """
    Parses a log line and returns a dictionary with its components.
    """
    pattern = r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (?P<level>[A-Z]+) - (?P<message>.*)$"
    match = re.match(pattern, log_line)

    if match:
        return match.groupdict()
    else:
        return {"timestamp": None, "level": None, "message": log_line}

def process_log_file(file_path):
    """
    Reads a log file and parses each line.
    """
    parsed_logs = []
    with open(file_path, 'r') as f:
        for line in f:
            parsed_logs.append(parse_log_line(line.strip()))
    return parsed_logs

def get_error_messages(parsed_logs):
    """
    Extracts error messages from a list of parsed log dictionaries.
    """
    errors = []
    for log_entry in parsed_logs:
        if log_entry.get('level') == 'ERROR':
            message = log_entry.get('message', 'No message')
            errors.append(message)
    return errors

def main():
    test_line_1 = '2023-10-26 10:30:00 - INFO - User logged in.'
    parsed_1 = parse_log_line(test_line_1)
    print(parsed_1)

    test_line_2 = '2023-10-26 11:00:00 - ERROR - File not found.'
    parsed_2 = parse_log_line(test_line_2)
    print(parsed_2)

if __name__ == "__main__":
    main()

