def validate_number(
    number: int,
) -> int:
    """Return the number unchanged, rejecting non-integers and negatives."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError(f"expected an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("negative numbers have no digit ordering here")
    return number


def digits_of(
    number: int,
) -> list[int]:
    """Split a non-negative integer into its decimal digits."""
    if number == 0:
        return [0]
    digits: list[int] = []
    while number > 0:
        number, digit = divmod(number, 10)
        digits.append(digit)
    digits.reverse()
    return digits


def digits_to_int(
    digits: list[int],
) -> int:
    """Rebuild an integer from digits, dropping any leading zeros."""
    value = 0
    for digit in digits:
        value = value * 10 + digit
    return value


def sort_digits(
    number: int,
) -> int:
    """Return the integer whose digits are those of `number`, ascending."""
    checked = validate_number(number)
    return digits_to_int(sorted(digits_of(checked)))


def digit_histogram(
    number: int,
) -> list[int]:
    """Count how often each decimal digit occurs in `number`."""
    counts = [0] * 10
    for digit in digits_of(validate_number(number)):
        counts[digit] += 1
    return counts


def describe_histogram(
    counts: list[int],
) -> str:
    """Render a digit histogram as a compact 'digit:count' listing."""
    parts = [f"{digit}:{count}" for digit, count in enumerate(counts) if count]
    return ", ".join(parts)


def format_row(
    number: int,
) -> str:
    """Build one report line for a single input number."""
    sorted_number = sort_digits(number)
    lost = len(digits_of(number)) - len(digits_of(sorted_number))
    note = f" (dropped {lost} leading zero{'s' if lost != 1 else ''})" if lost else ""
    summary = describe_histogram(digit_histogram(number))
    return f"{number:>8} -> {sorted_number:<8}{note}  [{summary}]"


def build_report(
    numbers: list[int],
) -> str:
    """Produce a multi-line report for a sequence of numbers."""
    return "\n".join(format_row(number) for number in numbers)


def main() -> None:
    samples: list[int] = [321, 5049, 0, 10, 987654321, 1000000]
    print(build_report(samples))
    total = sum(sort_digits(number) for number in samples)
    print(f"sum of sorted values: {total}")


if __name__ == "__main__":
    main()

