def validate_inputs(
    number: int,
    limit: int,
) -> tuple[int, int]:
    """Ensure both arguments are usable integers and the limit is positive."""
    if isinstance(number, bool) or isinstance(limit, bool):
        raise TypeError("number and limit must be integers, not booleans")
    if not isinstance(number, int) or not isinstance(limit, int):
        raise TypeError("number and limit must be integers")
    if limit < 1:
        raise ValueError("limit must be at least 1")
    return number, limit


def format_row(
    number: int,
    multiplier: int,
) -> str:
    """Build a single line such as '2 x 3 = 6'."""
    return f"{number} x {multiplier} = {number * multiplier}"


def generate_times_table(
    number: int,
    limit: int,
) -> list[str]:
    """Return the times table of `number` from 1 up to `limit` inclusive."""
    number, limit = validate_inputs(number, limit)
    return [format_row(number, multiplier) for multiplier in range(1, limit + 1)]


def align_rows(
    rows: list[str],
) -> list[str]:
    """Right-align the parts of each row so the '=' signs line up."""
    heads = [row.split(" = ")[0] for row in rows]
    tails = [row.split(" = ")[1] for row in rows]
    head_width = max(len(head) for head in heads)
    tail_width = max(len(tail) for tail in tails)
    return [
        f"{head:>{head_width}} = {tail:>{tail_width}}"
        for head, tail in zip(heads, tails)
    ]


def row_sum(
    rows: list[str],
) -> int:
    """Add up the products found on the right-hand side of each row."""
    return sum(int(row.rsplit("=", 1)[1]) for row in rows)


def table_report(
    number: int,
    limit: int,
) -> str:
    """Render a titled, aligned block of text for one times table."""
    rows = generate_times_table(number, limit)
    title = f"Times table for {number} (up to {limit})"
    underline = "-" * len(title)
    footer = f"sum of products: {row_sum(rows)}"
    return "\n".join([title, underline, *align_rows(rows), footer])


def main() -> None:
    for number, limit in [(2, 3), (5, 1), (7, 10), (-3, 4)]:
        print(table_report(number, limit))
        print()


if __name__ == "__main__":
    main()

