def is_brackets_balanced(s: str) -> bool:
    """
    Checks if a string has balanced and correctly nested brackets.
    """
    stack: list[str] = []
    mapping: dict[str, str] = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
    return not stack

def example_usage() -> None:
    """
    Demonstrates the usage of the is_brackets_balanced function.
    """
    test_cases: list[tuple[str, bool]] = [
        ('()[]{}', True),
        ('([{}])', True),
        ('({[})', False),
        (']', False),
        ('({[]})', True),
        ('', True),
        ('(()', False)
    ]
    for test_string, expected_result in test_cases:
        actual_result: bool = is_brackets_balanced(test_string)
        print(f"'{test_string}' is balanced: {actual_result} (Expected: {expected_result})")

if __name__ == "__main__":
    example_usage()

