class Meeting:
    def __init__(
        self,
        title: str,
        start: int,
        end: int,
    ) -> None:
        self.title = title
        self.start = start
        self.end = end

    def interval(self) -> tuple[int, int]:
        return (self.start, self.end)

    def label(self) -> str:
        return f"{self.title} {format_span(self.start, self.end)}"


def format_span(
    start: int,
    end: int,
) -> str:
    start_h, start_m = divmod(start, 60)
    end_h, end_m = divmod(end, 60)
    return f"{start_h:02d}:{start_m:02d}-{end_h:02d}:{end_m:02d}"


def has_overlap(
    meeting1: tuple[int, int],
    meeting2: tuple[int, int],
) -> bool:
    start1, end1 = meeting1
    start2, end2 = meeting2
    if start1 > end1 or start2 > end2:
        raise ValueError("a meeting cannot end before it starts")
    return start1 < end2 and start2 < end1


def overlap_minutes(
    meeting1: tuple[int, int],
    meeting2: tuple[int, int],
) -> int:
    if not has_overlap(meeting1, meeting2):
        return 0
    return min(meeting1[1], meeting2[1]) - max(meeting1[0], meeting2[0])


def find_conflicts(
    schedule: list[Meeting],
) -> list[tuple[int, int]]:
    conflicts = []
    for i, first in enumerate(schedule):
        for j in range(i + 1, len(schedule)):
            if has_overlap(first.interval(), schedule[j].interval()):
                conflicts.append((i, j))
    return conflicts


def conflict_report(
    schedule: list[Meeting],
) -> str:
    conflicts = find_conflicts(schedule)
    if not conflicts:
        return "No conflicts found."
    lines = []
    for i, j in conflicts:
        shared = overlap_minutes(schedule[i].interval(), schedule[j].interval())
        lines.append(
            f"{schedule[i].label()} overlaps {schedule[j].label()}"
            f" by {shared} min"
        )
    return "\n".join(lines)


def main() -> None:
    print(has_overlap((1, 5), (3, 7)))
    print(has_overlap((1, 2), (3, 4)))
    day = [
        Meeting("standup", 9 * 60, 9 * 60 + 15),
        Meeting("design review", 9 * 60, 10 * 60),
        Meeting("one-on-one", 10 * 60, 11 * 60),
        Meeting("retro", 10 * 60 + 45, 11 * 60 + 30),
    ]
    print(conflict_report(day))


if __name__ == "__main__":
    main()

