def normalize_rectangle(
    x1: int,
    y1: int,
    x2: int,
    y2: int,
) -> tuple[int, int, int, int]:
    """Return the rectangle as (left, bottom, right, top)."""
    left, right = min(x1, x2), max(x1, x2)
    bottom, top = min(y1, y2), max(y1, y2)
    return left, bottom, right, top


def is_point_in_rectangle(
    px: int,
    py: int,
    x1: int,
    y1: int,
    x2: int,
    y2: int,
) -> bool:
    """True when (px, py) is inside or on the border of the rectangle."""
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    return left <= px <= right and bottom <= py <= top


def is_point_on_border(
    px: int,
    py: int,
    x1: int,
    y1: int,
    x2: int,
    y2: int,
) -> bool:
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    if not is_point_in_rectangle(px, py, left, bottom, right, top):
        return False
    return px in (left, right) or py in (bottom, top)


def classify_point(
    px: int,
    py: int,
    x1: int,
    y1: int,
    x2: int,
    y2: int,
) -> str:
    if is_point_on_border(px, py, x1, y1, x2, y2):
        return "border"
    if is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "inside"
    return "outside"


def parse_point(
    text: str,
) -> tuple[int, int]:
    parts = text.replace("(", "").replace(")", "").split(",")
    if len(parts) != 2:
        raise ValueError("a point needs exactly two coordinates: " + text)
    return int(parts[0].strip()), int(parts[1].strip())


def format_report(
    points: list[tuple[int, int]],
    x1: int,
    y1: int,
    x2: int,
    y2: int,
) -> str:
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    lines = ["rectangle ({}, {})-({}, {})".format(left, bottom, right, top)]
    for px, py in points:
        kind = classify_point(px, py, left, bottom, right, top)
        lines.append("  ({:>3}, {:>3}) -> {}".format(px, py, kind))
    return "\n".join(lines)


if __name__ == "__main__":
