from typing import Iterable, List, Sequence, Union

Number = Union[int, float]


def validate_numbers(
    numbers: Sequence[Number],
) -> List[Number]:
    """Return the input as a list, rejecting non-numeric or too-short input."""
    checked: List[Number] = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"element {index} is not a number: {value!r}")
        checked.append(value)
    if len(set(checked)) < 2:
        raise ValueError("at least two distinct numbers are required")
    return checked


def find_second_smallest(
    numbers: Sequence[Number],
) -> Number:
    """Return the second smallest distinct value of the given numbers."""
    values: List[Number] = validate_numbers(numbers)
    smallest: Number = min(values)
    second: Number = max(values)
    for value in values:
        if smallest < value < second:
            second = value
    return second


def parse_numbers(
    text: str,
) -> List[Number]:
    """Parse a whitespace or comma separated list of numbers."""
    tokens: List[str] = text.replace(",", " ").split()
    parsed: List[Number] = []
    for token in tokens:
        number: float = float(token)
        parsed.append(int(number) if number.is_integer() else number)
    return parsed


def format_number(
    value: Number,
) -> str:
    """Render a number without a trailing ".0" for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(
    numbers: Sequence[Number],
) -> str:
    """Build a one-line report for a single list of numbers."""
    rendered: str = ", ".join(format_number(value) for value in numbers)
    try:
        result: str = format_number(find_second_smallest(numbers))
    except (TypeError, ValueError) as error:
        result = f"error ({error})"
    return f"[{rendered}] -> {result}"


def report(
    datasets: Iterable[str],
) -> str:
    """Parse each textual dataset and describe its second smallest number."""
    lines: List[str] = [describe(parse_numbers(text)) for text in datasets]
    return "\n".join(lines)


def main() -> None:
    datasets: List[str] = [
        "5 1 8 2 9",
        "10, 20, 30, 5",
        "3.5 -2 -2 0.25",
        "7 7 7",
    ]
    print(report(datasets))


if __name__ == "__main__":
    main()

