from typing import List, Tuple


def validate_principal(
    principal: float,
) -> float:
    if principal < 0:
        raise ValueError("principal must be non-negative")
    return float(principal)


def validate_rate(
    rate: float,
) -> float:
    if rate < 0:
        raise ValueError("rate must be non-negative")
    return float(rate)


def validate_time(
    time: int,
) -> int:
    if time < 0:
        raise ValueError("time must be non-negative")
    return int(time)


def calculate_simple_interest(
    principal: float,
    rate: float,
    time: int,
) -> float:
    p: float = validate_principal(principal)
    r: float = validate_rate(rate)
    t: int = validate_time(time)
    return p * r * t / 100.0


def yearly_schedule(
    principal: float,
    rate: float,
    time: int,
) -> List[Tuple[int, float, float]]:
    rows: List[Tuple[int, float, float]] = []
    for year in range(1, validate_time(time) + 1):
        interest: float = calculate_simple_interest(principal, rate, year)
        rows.append((year, interest, principal + interest))
    return rows


def format_money(
    value: float,
) -> str:
    return "{:>12,.2f}".format(value)


def build_report(
    principal: float,
    rate: float,
    time: int,
) -> str:
    title: str = "Principal {} at {:.2f}% for {} year(s)".format(
        format_money(principal).strip(), validate_rate(rate), validate_time(time)
    )
    lines: List[str] = [title, "{:>4s} {:>12s} {:>12s}".format("Year", "Interest", "Balance")]
    for year, interest, balance in yearly_schedule(principal, rate, time):
        lines.append("{:>4d} {} {}".format(year, format_money(interest), format_money(balance)))
    total: float = principal + calculate_simple_interest(principal, rate, time)
    lines.append("Total amount due: {}".format(format_money(total).strip()))
    return "\n".join(lines)


def main() -> None:
    cases: List[Tuple[float, float, int]] = [(1000.0, 5.0, 2), (500.0, 2.5, 10)]
    for principal, rate, time in cases:
        print(build_report(principal, rate, time))


if __name__ == "__main__":
    main()

