SEPARATORS: str = " -"


def digits_of(
    card_number: str,
    separators: str,
) -> list[int]:
    """Return the digits of a card number after dropping the separators."""
    cleaned: str = card_number
    for separator in separators:
        cleaned = cleaned.replace(separator, "")
    if not cleaned.isdigit():
        raise ValueError("card number must contain digits only: %r" % card_number)
    return [int(character) for character in cleaned]


def checksum(
    digits: list[int],
) -> int:
    """Sum the digits, doubling every second one counted from the right."""
    total: int = 0
    for position, digit in enumerate(reversed(digits)):
        if position % 2 == 0:
            total += digit
        else:
            doubled: int = digit * 2
            total += doubled - 9 if doubled > 9 else doubled
    return total


def is_valid_luhn(
    card_number: str,
) -> bool:
    """Return True when the card number's checksum is a multiple of ten."""
    digits: list[int] = digits_of(card_number, SEPARATORS)
    if len(digits) < 2:
        return False
    return checksum(digits) % 10 == 0


def describe(
    card_number: str,
    separators: str,
) -> str:
    """Build a one-line human readable report for a single card number."""
    try:
        digits: list[int] = digits_of(card_number, separators)
    except ValueError as error:
        return "%-20s rejected (%s)" % (card_number, error)
    total: int = checksum(digits)
    verdict: str = "VALID" if is_valid_luhn(card_number) else "INVALID"
    plain: str = "".join(str(digit) for digit in digits)
    return "%-20s sum=%-4d %s" % (plain, total, verdict)


def report(
    card_numbers: list[str],
    separators: str,
) -> str:
    """Join the descriptions of several card numbers into a report block."""
    return "\n".join(describe(number, separators) for number in card_numbers)


def main() -> None:
    samples: list[str] = [
        "49927398716",
        "1234567890123456",
        "4539 1488 0343 6467",
        "8",
        "4111-1111-1111-111X",
    ]
    print(report(samples, SEPARATORS))


if __name__ == "__main__":
    main()

