def filter_dict_by_value(input_dict: dict[str, int | float], threshold: int | float) -> dict[str, int | float]:
    """
    Filters a dictionary to include only key-value pairs where the value is greater than a specified threshold.

    Args:
        input_dict: The input dictionary. Keys are strings, values are numbers.
        threshold: The threshold value.

    Returns:
        A new dictionary containing only the key-value pairs where the value exceeds the threshold.
    """
    filtered_dict: dict[str, int | float] = {}
    for key, value in input_dict.items():
        if value > threshold:
            filtered_dict[key] = value
    return filtered_dict

def main() -> None:
    dict1: dict[str, int] = {'a': 10, 'b': 20, 'c': 5}
    threshold1: int = 15
    result1: dict[str, int] = filter_dict_by_value(dict1, threshold1)
    print(result1)

    dict2: dict[str, int] = {'x': 1, 'y': 2}
    threshold2: int = 5
    result2: dict[str, int] = filter_dict_by_value(dict2, threshold2)
    print(result2)

    dict3: dict[str, float] = {'m': 3.5, 'n': 7.2, 'o': 2.1}
