def filter_dict_by_value(input_dict, threshold):
    """
    Filters a dictionary to include only key-value pairs where the value is greater than a specified threshold.

    Args:
        input_dict: The input dictionary. Keys are strings, values are numbers.
        threshold: The threshold value.

    Returns:
        A new dictionary containing only the key-value pairs where the value exceeds the threshold.
    """
    filtered_dict = {}
    for key, value in input_dict.items():
        if value > threshold:
            filtered_dict[key] = value
    return filtered_dict

