def validate_measurements(
    weight_kg: float,
    height_m: float,
) -> None:
    if weight_kg <= 0:
        raise ValueError("weight_kg must be positive")
    if height_m <= 0:
        raise ValueError("height_m must be positive")


def calculate_bmi(
    weight_kg: float,
    height_m: float,
) -> float:
    validate_measurements(weight_kg, height_m)
    return round(weight_kg / (height_m * height_m), 2)


def classify_bmi(
    bmi: float,
) -> str:
    if bmi < 18.5:
        return "Underweight"
    if bmi < 25.0:
        return "Normal weight"
    if bmi < 30.0:
        return "Overweight"
    return "Obese"


def healthy_weight_range(
    height_m: float,
) -> tuple[float, float]:
    area: float = height_m * height_m
    return round(18.5 * area, 1), round(24.9 * area, 1)


def parse_record(
    line: str,
) -> tuple[str, float, float]:
    parts: list[str] = [field.strip() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError("expected 'name, weight_kg, height_m' but got: " + line)
    name, raw_weight, raw_height = parts
    return name, float(raw_weight), float(raw_height)


def build_report(
    records: list[str],
) -> list[dict[str, object]]:
    report: list[dict[str, object]] = []
    for line in records:
        name, weight_kg, height_m = parse_record(line)
        bmi: float = calculate_bmi(weight_kg, height_m)
        low, high = healthy_weight_range(height_m)
        report.append({
            "name": name,
            "bmi": bmi,
            "category": classify_bmi(bmi),
            "healthy_min": low,
            "healthy_max": high,
        })
    return report


def format_row(
    entry: dict[str, object],
) -> str:
    template: str = "{:<8} {:>6.2f}  {:<14} healthy: {}-{} kg"
    return template.format(
        entry["name"],
        entry["bmi"],
        entry["category"],
        entry["healthy_min"],
        entry["healthy_max"],
    )


def average_bmi(
    report: list[dict[str, object]],
) -> float:
    total: float = sum(float(entry["bmi"]) for entry in report)
    return round(total / len(report), 2)


def main() -> None:
    records: list[str] = ["Ana, 70, 1.75", "Bruno, 90, 1.80", "Clara, 52, 1.68"]
    report = build_report(records)
    for entry in report:
        print(format_row(entry))
    print("group average BMI: {:.2f}".format(average_bmi(report)))


if __name__ == "__main__":
    main()

