def validate_inputs(
    principal: float,
    rate: float,
    compounding_frequency: int,
    time_years: int,
) -> None:
    if principal < 0:
        raise ValueError("principal must be non-negative")
    if rate < -1:
        raise ValueError("rate must be at least -1")
    if compounding_frequency < 1:
        raise ValueError("compounding_frequency must be at least 1")
    if time_years < 0:
        raise ValueError("time_years must be non-negative")


def calculate_compound_interest(
    principal: float,
    rate: float,
    compounding_frequency: int,
    time_years: int,
) -> float:
    validate_inputs(principal, rate, compounding_frequency, time_years)
    periods = compounding_frequency * time_years
    growth = (1.0 + rate / compounding_frequency) ** periods
    return principal * growth


def effective_annual_rate(
    rate: float,
    compounding_frequency: int,
) -> float:
    return (1.0 + rate / compounding_frequency) ** compounding_frequency - 1.0


def yearly_schedule(
    principal: float,
    rate: float,
    compounding_frequency: int,
    time_years: int,
) -> list[tuple[int, float, float]]:
    schedule = []
    for year in range(1, time_years + 1):
        balance = calculate_compound_interest(
            principal, rate, compounding_frequency, year
        )
        schedule.append((year, balance, balance - principal))
    return schedule


def format_schedule(
    schedule: list[tuple[int, float, float]],
) -> str:
    lines = ["Year |      Balance |     Interest"]
    for year, balance, earned in schedule:
        lines.append("{:>4} | {:>12,.2f} | {:>12,.2f}".format(year, balance, earned))
    return "\n".join(lines)


def compare_frequencies(
    principal: float,
    rate: float,
    time_years: int,
    frequencies: list[int],
) -> dict[int, float]:
    results = {}
    for frequency in frequencies:
        results[frequency] = calculate_compound_interest(
            principal, rate, frequency, time_years
        )
    return results


def main() -> None:
    print(calculate_compound_interest(1000, 0.05, 1, 1))
    print(calculate_compound_interest(1000, 0.05, 4, 1))
    print(format_schedule(yearly_schedule(1000, 0.05, 12, 5)))
    totals = compare_frequencies(1000, 0.05, 10, [1, 4, 12, 365])
    for frequency, total in totals.items():
        rate_pct = effective_annual_rate(0.05, frequency) * 100
        print("n={:<4} total={:,.2f} effective={:.4f}%".format(frequency, total, rate_pct))


if __name__ == "__main__":
    main()

