HEX_DIGITS = "0123456789abcdefABCDEF"


def decode_escape(
    text: str,
    start: int,
) -> tuple[str, int]:
    """Decode a %XX escape at ``start``; return the character and the next index."""
    hex_digits = text[start + 1:start + 3]
    if text[start] == "%" and len(hex_digits) == 2 and all(d in HEX_DIGITS for d in hex_digits):
        return chr(int(hex_digits, 16)), start + 3
    return text[start], start + 1


def decode_component(
    text: str
) -> str:
    """Expand every %XX escape in a key or value, leaving '+' untouched."""
    out = []
    index = 0
    while index < len(text):
        char, index = decode_escape(text, index)
        out.append(char)
    return "".join(out)


def split_pair(
    segment: str,
    separator: str,
) -> tuple[str, str]:
    """Split one segment at the first separator and decode both halves."""
    key, value = segment, ""
    if separator in segment:
        key, value = segment.split(separator, 1)
    return decode_component(key), decode_component(value)


def parse_url_params(
    query_string: str
) -> dict[str, str]:
    """Parse a URL query string into a dictionary of key-value pairs."""
    body = query_string.lstrip("?").split("#", 1)[0]
    params = {}
    for segment in body.split("&"):
        if not segment:
            continue
        key, value = split_pair(segment, "=")
        if key:
            params[key] = value
    return params


def format_params(
    params: dict[str, str],
    title: str,
) -> str:
    """Build an aligned report of the parsed parameters under a heading."""
    lines = [f"query: {title}"]
    if params:
        width = max(len(key) for key in params)
        lines.extend(f"  {key.ljust(width)} : {value}" for key, value in params.items())
    else:
        lines.append("  (no parameters)")
    return "\n".join(lines)


def main() -> None:
    queries = [
        "name=John&age=30",
        "q=python+programming",
        "?path=%2Fhome%2Fuser&flag&depth=2#top",
        "",
    ]
    for query in queries:
        print(format_params(parse_url_params(query), query))
        print()


if __name__ == "__main__":
    main()

