def roman_to_int(roman_numeral: str) -> int:
    roman_map: dict[str, int] = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    integer_value: int = 0
    previous_value: int = 0

    for char in reversed(roman_numeral):
        current_value: int = roman_map[char]
        if current_value < previous_value:
            integer_value -= current_value
        else:
            integer_value += current_value
        previous_value = current_value
    return integer_value

def main() -> None:
    print(f"'III' -> {roman_to_int('III')}")
    print(f"'LVIII' -> {roman_to_int('LVIII')}")
    print(f"'MCMXCIV' -> {roman_to_int('MCMXCIV')}")

