def is_perfect_number(number: int) -> bool:
    """
    Checks if a given positive integer is a perfect number.

    A perfect number is a positive integer that is equal to the sum of its
    proper positive divisors, excluding the number itself.
    """
    if number <= 0:
        return False

    divisor_sum: int = 0
    for i in range(1, int(number**0.5) + 1):
        if number % i == 0:
            divisor_sum += i
            if i * i != number and i != 1:
                divisor_sum += number // i

    return divisor_sum == number

