FEET_PER_METER = 3.28084
VALID_UNITS = frozenset({"m", "ft"})


def normalize_unit(
    unit: str,
) -> str:
    cleaned = unit.strip().lower()
    if cleaned not in VALID_UNITS:
        raise ValueError(f"unsupported unit: {unit!r}")
    return cleaned


def to_meters(
    value: float,
    from_unit: str,
) -> float:
    if from_unit == "ft":
        return value / FEET_PER_METER
    return value


def from_meters(
    meters: float,
    to_unit: str,
) -> float:
    if to_unit == "ft":
        return meters * FEET_PER_METER
    return meters


def convert_length(
    value: float,
    from_unit: str,
    to_unit: str,
) -> float:
    source = normalize_unit(from_unit)
    target = normalize_unit(to_unit)
    return from_meters(to_meters(float(value), source), target)


def parse_request(
    text: str,
) -> tuple[float, str, str]:
    parts = text.split()
    if len(parts) != 4 or parts[2] != "to":
        raise ValueError(f"cannot parse request: {text!r}")
    return float(parts[0]), parts[1], parts[3]


def format_result(
    value: float,
    unit: str,
    digits: int = 5,
) -> str:
    return f"{round(value, digits):g} {unit}"


def convert_request(
    text: str,
) -> str:
    value, from_unit, to_unit = parse_request(text)
    result = convert_length(value, from_unit, to_unit)
    return format_result(result, normalize_unit(to_unit))


def build_report(
    requests: list[str],
) -> str:
    lines = []
    for request in requests:
        try:
            answer = convert_request(request)
        except ValueError as error:
            answer = f"error ({error})"
        lines.append(f"{request:>20} = {answer}")
    return "\n".join(lines)


