def reverse_string(
    input_string: str,
) -> str:
    """Return a new string with the characters of input_string in reverse order."""
    if not isinstance(input_string, str):
        raise TypeError("input_string must be a str")
    characters = list(input_string)
    characters.reverse()
    return "".join(characters)


def reverse_words(
    sentence: str,
) -> str:
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    return " ".join(reversed(sentence.split()))


def reverse_each_word(
    sentence: str,
) -> str:
    """Reverse the characters inside every word, leaving the word order alone."""
    return " ".join(reverse_string(word) for word in sentence.split())


def normalize(
    text: str,
) -> str:
    """Lower-case the text and drop everything that is not alphanumeric."""
    return "".join(char.lower() for char in text if char.isalnum())


def is_palindrome(
    text: str,
) -> bool:
    """Report whether text reads the same forwards and backwards."""
    cleaned = normalize(text)
    return cleaned == reverse_string(cleaned)


def longest_reversible_run(
    text: str,
) -> str:
    """Return the longest substring of text that is itself a palindrome."""
    best = ""
    for start in range(len(text)):
        for end in range(start + 1, len(text) + 1):
            candidate = text[start:end]
            if len(candidate) > len(best) and candidate == reverse_string(candidate):
                best = candidate
    return best


def describe(
    text: str,
) -> str:
    """Build a one-line human-readable summary of the reversals of text."""
    return " | ".join(
        [
            f"original      : {text!r}",
            f"reversed      : {reverse_string(text)!r}",
            f"words reversed: {reverse_words(text)!r}",
            f"each word     : {reverse_each_word(text)!r}",
            f"palindrome    : {is_palindrome(text)}",
            f"longest run   : {longest_reversible_run(text)!r}",
        ]
    )


def build_report(
    samples: list[str],
) -> str:
    """Join the descriptions of several samples into a multi-line report."""
    return "\n".join(describe(sample) for sample in samples)


