def calculate_power(
    base: float,
    exponent: int
) -> float:
    if exponent < 0:
        base = 1 / base
        exponent = -exponent

    result: float = 1.0
    current_base: float = float(base)
    current_exponent: int = exponent

    while current_exponent > 0:
        if current_exponent % 2 == 1:
            result = result * current_base
        current_base = current_base * current_base
        current_exponent = current_exponent // 2
    return result

