def validate(
    numbers: list[int],
) -> list[int]:
    """Return the input as a list, rejecting anything that is not at least
    four positive integers."""
    values: list[int] = list(numbers)
    if len(values) < 4:
        raise ValueError("at least four numbers are required")
    for value in values:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("all entries must be plain integers")
        if value <= 0:
            raise ValueError("all entries must be positive")
    return values


def two_smallest(
    numbers: list[int],
) -> tuple[int, int]:
    """Find the two smallest entries in a single pass."""
    smallest: int = numbers[0]
    second: int = numbers[1]
    if second < smallest:
        smallest, second = second, smallest
    for value in numbers[2:]:
        if value < smallest:
            smallest, second = value, smallest
        elif value < second:
            second = value
    return smallest, second


def sum_two_smallest(
    numbers: list[int],
) -> int:
    """Sum of the two smallest positive numbers of the list."""
    values: list[int] = validate(numbers)
    low, next_low = two_smallest(values)
    return low + next_low


def parse_line(
    line: str,
) -> list[int]:
    """Turn a whitespace or comma separated line into a list of integers."""
    cleaned: str = line.replace(",", " ")
    return [int(token) for token in cleaned.split()]


def format_result(
    numbers: list[int],
    total: int,
) -> str:
    rendered: str = ", ".join(str(value) for value in numbers)
    return "[{0}] -> {1}".format(rendered, total)


def report(
    lines: list[str],
) -> list[str]:
    """Process each input line and describe the outcome."""
    output: list[str] = []
    for line in lines:
        numbers = parse_line(line)
        try:
            total = sum_two_smallest(numbers)
        except (TypeError, ValueError) as error:
            output.append("[{0}] -> error: {1}".format(line.strip(), error))
        else:
            output.append(format_result(numbers, total))
    return output


def main() -> None:
    samples: list[str] = [
        "19 5 42 2 77",
        "10, 343445353, 3453445, 3453545353453",
        "1 2 3",
        "4 -1 8 12",
    ]
    for line in report(samples):
        print(line)


if __name__ == "__main__":
    main()

