    rendered = ", ".join(str(value) for value in numbers)
    return "[{0}] -> {1}".format(rendered, total)


def report(
    lines,
):
    """Process each input line and describe the outcome."""
    output = []
    for line in lines:
        numbers = parse_line(line)
        try:
            total = sum_two_smallest(numbers)
        except (TypeError, ValueError) as error:
            output.append("[{0}] -> error: {1}".format(line.strip(), error))
        else:
            output.append(format_result(numbers, total))
    return output


def main():
    samples = [
        "19 5 42 2 77",
        "10, 343445353, 3453445, 3453545353453",
        "1 2 3",
        "4 -1 8 12",
    ]
    for line in report(samples):
        print(line)


