import os
from typing import Iterable, List, Optional, Tuple


def append_to_file(
    filepath: str,
    content: str,
) -> bool:
    """Append content to filepath, returning True on success."""
    try:
        with open(filepath, "a", encoding="utf-8") as handle:
            handle.write(content)
    except OSError:
        return False
    return True


def append_line(
    filepath: str,
    line: str,
) -> bool:
    """Append a single line, adding the newline terminator if missing."""
    payload: str = line if line.endswith("\n") else line + "\n"
    return append_to_file(filepath, payload)


def append_many(
    filepath: str,
    lines: Iterable[str],
) -> Tuple[int, int]:
    """Append several lines, returning the (written, failed) counts."""
    written: int = 0
    failed: int = 0
    for line in lines:
        if append_line(filepath, line):
            written += 1
        else:
            failed += 1
    return written, failed


def file_size(
    filepath: str,
) -> Optional[int]:
    """Size of filepath in bytes, or None when it cannot be inspected."""
    try:
        return os.path.getsize(filepath)
    except OSError:
        return None


def read_back(
    filepath: str,
) -> List[str]:
    """Return the stored lines without their trailing newlines."""
    try:
        with open(filepath, "r", encoding="utf-8") as handle:
            return handle.read().splitlines()
    except OSError:
        return []


def format_report(
    filepath: str,
    written: int,
    failed: int,
) -> str:
    """Build a one-line human readable summary of an append run."""
    size: Optional[int] = file_size(filepath)
    size_text: str = "unavailable" if size is None else f"{size} bytes"
    return f"{filepath}: {written} written, {failed} failed, size {size_text}"


def main() -> int:
    target: str = "test.txt"
