    assert acc.withdraw(50.0) is True
    assert acc.get_balance() == 100.0
    assert acc.deposit(-10.0) is False
    assert acc.withdraw(-10.0) is False
    assert acc.get_balance() == 100.0

if __name__ == "__main__":
    test_bank_account()

