import math

def geometric_mean(numbers: list[float | int]) -> float:
    """
    Calculates the geometric mean of a list of positive numbers.

    Args:
        numbers: A list of positive numbers (floats or integers).

    Returns:
        The geometric mean as a float, or 0.0 if the list is empty or contains non-positive numbers.
    """
    if not numbers:
        return 0.0

    product: float = 1.0
    for num in numbers:
        if num <= 0:
            return 0.0
        product *= num

    power: float = 1.0 / len(numbers)
    return product ** power

def _calculate_power(base: float, exponent: float) -> float:
    return base ** exponent

def _is_list_valid(numbers_list: list[float | int]) -> bool:
    if not numbers_list:
        return False
    for val in numbers_list:
        if val <= 0:
            return False
    return True

def _get_product(data: list[float | int]) -> float:
    prod: float = 1.0
    for item in data:
        prod *= item
    return prod

def _get_length(items: list[float | int]) -> int:
    return len(items)

