def validate_key(
    key_char: str,
) -> str:
    """Return the key character, rejecting anything that is not a single char."""
    if not isinstance(key_char, str):
        raise TypeError("key_char must be a string")
    if len(key_char) != 1:
        raise ValueError("key_char must be exactly one character")
    return key_char


def xor_cipher(
    text: str,
    key_char: str,
) -> str:
    """XOR every character of text with key_char and return the result."""
    key: int = ord(validate_key(key_char))
    return "".join(chr(ord(ch) ^ key) for ch in text)


def to_hex(
    text: str,
) -> str:
    """Render a (possibly unprintable) string as space separated hex bytes."""
    return " ".join(f"{ord(ch):02x}" for ch in text)


def is_reversible(
    text: str,
    key_char: str,
) -> bool:
    """True when encrypting twice with the same key restores the original text."""
    return xor_cipher(xor_cipher(text, key_char), key_char) == text


def crack_single_key(
    cipher: str,
    expected_prefix: str,
) -> str:
    """Recover the key character of a cipher whose plaintext prefix is known."""
    if not expected_prefix:
        raise ValueError("expected_prefix must not be empty")
    if len(cipher) < len(expected_prefix):
        raise ValueError("cipher is shorter than the expected prefix")
    key_char: str = chr(ord(cipher[0]) ^ ord(expected_prefix[0]))
    if xor_cipher(cipher[: len(expected_prefix)], key_char) != expected_prefix:
        raise ValueError("no single key character matches the expected prefix")
    return key_char


def format_row(
    text: str,
    key_char: str,
) -> str:
    """Format one report line: plaintext, cipher in hex and round trip status."""
    cipher: str = xor_cipher(text, key_char)
    mark: str = "ok" if is_reversible(text, key_char) else "FAILED"
    return f"{text:<12} -> {to_hex(cipher):<20} [{mark}]"


def main() -> int:
    key: str = "B"
    messages: list[str] = ["Hello", "Test", "xor cipher"]
    for message in messages:
        print(format_row(message, key))
    ciphers: list[str] = [xor_cipher(message, key) for message in messages]
    for cipher in ciphers:
        print(f"{to_hex(cipher)} decodes to {xor_cipher(cipher, key)!r}")
    recovered: str = crack_single_key(ciphers[1], "Te")
    print(f"recovered key: {recovered!r}")
    print(f"decrypted with recovered key: {xor_cipher(ciphers[1], recovered)!r}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

