def is_valid_hex_color(
    code: str,
) -> bool:
    if not isinstance(code, str):
        return False
    if not code.startswith("#"):
        return False
    body: str = code[1:]
    if len(body) not in (3, 6):
        return False
    return all(ch in HEX_DIGITS for ch in body)


def normalize_hex_color(
    code: str,
) -> str:
    if not is_valid_hex_color(code):
        raise ValueError("not a valid hex color: %r" % (code,))
    body: str = code[1:]
    if len(body) == 3:
        body = "".join(ch * 2 for ch in body)
    return "#" + body.upper()


def hex_to_rgb(
    code: str,
) -> tuple[int, int, int]:
    full: str = normalize_hex_color(code)
    red: int = int(full[1:3], 16)
    green: int = int(full[3:5], 16)
    blue: int = int(full[5:7], 16)
    return red, green, blue


