def generate_permutations(
    lst: list,
) -> list:
    """Return every ordering of the elements of ``lst`` as a list of lists."""
    if len(lst) <= 1:
        return [list(lst)]
    result: list = []
    for index in range(len(lst)):
        head: object = lst[index]
        rest: list = list(lst[:index]) + list(lst[index + 1:])
        for tail in generate_permutations(rest):
            result.append([head] + tail)
    return result


def count_permutations(
    size: int,
) -> int:
    """Number of orderings of ``size`` distinct items (factorial)."""
    if size < 0:
        raise ValueError("size must be non-negative")
    total: int = 1
    for factor in range(2, size + 1):
        total *= factor
    return total


def unique_permutations(
    lst: list,
) -> list:
    """Permutations with duplicate orderings removed, original order kept."""
    seen: set = set()
    unique: list = []
    for perm in generate_permutations(lst):
        key: tuple = tuple(perm)
        if key not in seen:
            seen.add(key)
            unique.append(perm)
    return unique


def format_permutation(
    perm: list,
) -> str:
    """Render a single permutation as a compact, readable string."""
    return "(" + ", ".join(repr(item) for item in perm) + ")"


def describe(
    lst: list,
) -> str:
    """Build a short report about all permutations of ``lst``."""
    perms: list = generate_permutations(lst)
    expected: int = count_permutations(len(lst))
    distinct: list = unique_permutations(lst)
    lines: list = [
        "input: {0}".format(list(lst)),
        "generated {0} permutations (expected {1}, distinct {2})".format(
            len(perms), expected, len(distinct)
        ),
    ]
    for perm in distinct:
        lines.append("  " + format_permutation(perm))
    return "\n".join(lines)


def main() -> None:
    samples: list = [
        [1, 2],
        ["a"],
        [],
        ["x", "y", "z"],
        [1, 1, 2],
    ]
    for sample in samples:
        print(describe(sample))
        print()


if __name__ == "__main__":
    main()

