import math

def is_prime(n: int) -> bool:
    """
    Checks if a given integer n is a prime number.

    Args:
        n: The integer to check.

    Returns:
        True if n is prime, False otherwise.
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    i: int = 3
    limit: int = int(math.sqrt(n)) + 1
    while i <= limit:
        if n % i == 0:
            return False
        i += 2
    return True

