def find_divisors(n: int) -> list[int]:
    """
    Finds all positive divisors of a given positive integer n.

    Args:
        n: The positive integer for which to find divisors.

    Returns:
        A list of all positive divisors of n, in ascending order.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    divs: list[int] = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i * i != n:
                divs.append(n // i)
    divs.sort()
    return divs

def _is_prime(num: int) -> bool:
    """
    Helper function to check if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def get_divisor_count(n: int) -> int:
    """
    Returns the number of divisors for a positive integer n.
    """
    return len(find_divisors(n))

def get_sum_of_divisors(n: int) -> int:
    """
    Calculates the sum of all positive divisors for a positive integer n.
    """
    total_sum: int = 0
    for divisor in find_divisors(n):
        total_sum += divisor
    return total_sum

