def binary_search(sorted_list: list[int], target: int) -> int:
    """
    Searches for a target number within a sorted list using binary search.
    """
    low: int = 0
    high: int = len(sorted_list) - 1

    while low <= high:
        mid: int = (low + high) // 2
        mid_value: int = sorted_list[mid]

        if mid_value == target:
            return mid
        elif mid_value < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

