def filter_dict_by_value(data_dict: dict[str, float], min_value: float) -> dict[str, float]:
    """
    Filters a dictionary by its values, keeping only pairs where the value is greater than or equal to min_value.

    Args:
        data_dict: The input dictionary with string keys and numeric values.
        min_value: The minimum value to filter by.

    Returns:
        A new dictionary containing the filtered key-value pairs.
    """
    filtered_dict: dict[str, float] = {}
    for key, value in data_dict.items():
        if value >= min_value:
            filtered_dict[key] = value
    return filtered_dict

