def power_recursive(base: int, exponent: int) -> int:
    """
    Calculates base raised to the power of exponent using recursion.
    Assumes exponent is non-negative.
    """
    if exponent == 0:
        return 1
    elif exponent == 1:
        return base
    else:
        # For even exponents, we can optimize by squaring the result of base^(exponent/2)
        if exponent % 2 == 0:
            half_power: int = power_recursive(base, exponent // 2)
            return half_power * half_power
        # For odd exponents, it's base * base^(exponent-1)
        else:
            result: int = base * power_recursive(base, exponent - 1)
            return result

def main() -> None:
    test_cases: list[tuple[int, int, int]] = [
