def justify_text_simple(words: list[str], max_width: int) -> str:
    """
    Justifies a list of words into a single line, padding with spaces.

    Args:
        words: A list of words (strings) to justify.
        max_width: The maximum width of the line (int).

    Returns:
        A string representing the justified text.
    """
    if not words:
        return ""

    line: list[str] = []
    current_length: int = 0

    for word in words:
        if not line:
            line.append(word)
            current_length = len(word)
        else:
            line.append(' ')
            line.append(word)
            current_length += 1 + len(word)

    num_spaces_to_add: int = max_width - current_length
    if num_spaces_to_add <= 0:
        return "".join(line)

    result_line: list[str] = []
    space_slots: int = line.count(' ')
    if space_slots == 0:
        return "".join(line) + " " * num_spaces_to_add

    base_spaces_per_slot: int = num_spaces_to_add // space_slots
    extra_spaces_slots: int = num_spaces_to_add % space_slots

    space_count: int = 0
    for item in line:
        if item == ' ':
            result_line.append(' ')
            result_line.append(' ' * base_spaces_per_slot)
            if space_count < extra_spaces_slots:
                result_line.append(' ')
                space_count += 1
        else:
            result_line.append(item)

    return "".join(result_line)

