def is_valid_us_zip_code(zip_code: str) -> bool:
    """
    Validates if a given string is a valid US zip code.

    A valid zip code is a string of exactly 5 digits.
    """
    if not isinstance(zip_code, str):
        return False
    if len(zip_code) != 5:
        return False
    return zip_code.isdigit()

def check_zip_codes(zip_codes: list[str]) -> list[bool]:
    """
    Checks a list of zip codes for validity.
    """
    results: list[bool] = []
    for code in zip_codes:
        results.append(is_valid_us_zip_code(code))
    return results

def get_first_valid_zip(codes: list[str]) -> str | None:
    """
    Returns the first valid zip code from a list, or None if none are valid.
    """
    for code in codes:
        if is_valid_us_zip_code(code):
            return code
    return None

def main() -> None:
    test_cases: list[str] = ['90210', '1234', 'abcde', '123456', '']
    for case in test_cases:
        print(f"'{case}' is valid: {is_valid_us_zip_code(case)}")

    batch_results: list[bool] = check_zip_codes(test_cases)
    print(f"Batch results: {batch_results}")

    first_valid: str | None = get_first_valid_zip(['invalid', '11111', '222', '33333'])
    print(f"First valid zip: {first_valid}")

if __name__ == '__main__':
    main()

