def has_unmet_dependencies(task_name: str, tasks: list[dict[str, any]], completed_tasks: list[str]) -> bool:
    """
    Checks if a given task has any unmet dependencies.

    Args:
        task_name: The name of the task to check.
        tasks: A list of task dictionaries, each with 'name' and 'dependencies'.
        completed_tasks: A list of names of tasks that have been completed.

    Returns:
        True if any dependency for the task is not in completed_tasks, False otherwise.
    """
    target_task_dependencies: list[str] = []
    for task_info in tasks:
        if task_info['name'] == task_name:
            target_task_dependencies = task_info['dependencies']
            break

    for dependency in target_task_dependencies:
        if dependency not in completed_tasks:
            return True
    return False

def get_task_dependencies(task_name: str, tasks: list[dict[str, any]]) -> list[str]:
    """Retrieves the dependencies for a given task name."""
    for task_info in tasks:
        if task_info['name'] == task_name:
            return task_info['dependencies']
    return []

def check_all_dependencies_met(dependencies: list[str], completed: list[str]) -> bool:
    """Checks if all specified dependencies are present in the completed list."""
    return all(dep in completed for dep in dependencies)

