from typing import Dict, List, Sequence, Tuple


def validate_ratings(
    movie_ratings: Dict[str, List[float]],
) -> None:
    """Raise a descriptive error if the input is not a title -> ratings mapping."""
    if not isinstance(movie_ratings, dict):
        raise TypeError("movie_ratings must be a dictionary of titles to rating lists")
    for title, ratings in movie_ratings.items():
        if not isinstance(title, str):
            raise TypeError(f"movie title must be a string, got {type(title).__name__}")
        if not isinstance(ratings, (list, tuple)):
            raise TypeError(f"ratings for {title!r} must be a list of numbers")
        for rating in ratings:
            if isinstance(rating, bool) or not isinstance(rating, (int, float)):
                raise TypeError(f"rating {rating!r} for {title!r} is not numeric")


def average_of(
    ratings: Sequence[float],
) -> float:
    """Arithmetic mean of the ratings, or 0.0 when there are none."""
    if not ratings:
        return 0.0
    return sum(ratings) / len(ratings)


def get_average_movie_rating(
    movie_ratings: Dict[str, List[float]],
) -> Dict[str, float]:
    """Map each movie title to the average of its ratings (0.0 if unrated)."""
    validate_ratings(movie_ratings)
    return {title: average_of(ratings) for title, ratings in movie_ratings.items()}


def rank_movies(
    averages: Dict[str, float],
) -> List[Tuple[str, float]]:
    """Titles with their averages, best first, ties broken alphabetically."""
    return sorted(averages.items(), key=lambda item: (-item[1], item[0]))


def count_ratings(
    movie_ratings: Dict[str, List[float]],
) -> Dict[str, int]:
    """Number of ratings collected for each movie."""
    return {title: len(ratings) for title, ratings in movie_ratings.items()}


def format_row(
    title: str,
    average: float,
    votes: int,
) -> str:
    """Render one report line, marking movies that nobody has rated yet."""
    if votes == 0:
        return f"{title:<12} {'unrated':>9} (0 votes)"
    label = "vote" if votes == 1 else "votes"
    return f"{title:<12} {average:>9.2f} ({votes} {label})"


def build_report(
    movie_ratings: Dict[str, List[float]],
) -> str:
    """Full ranking report for a collection of movie ratings."""
    averages = get_average_movie_rating(movie_ratings)
    votes = count_ratings(movie_ratings)
    lines = [format_row(title, average, votes[title]) for title, average in rank_movies(averages)]
    overall = average_of([r for ratings in movie_ratings.values() for r in ratings])
    lines.append(f"{'OVERALL':<12} {overall:>9.2f}")
    return "\n".join(lines)


def main() -> int:
    catalogue: Dict[str, List[float]] = {
        "Movie A": [5, 4, 5],
        "Movie B": [3, 2],
        "Movie C": [],
        "Movie D": [10],
    }
    print(get_average_movie_rating(catalogue))
    print(build_report(catalogue))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

