import re

PHONE_PATTERN: re.Pattern[str] = re.compile(r"^\d{3}([- ]?)\d{3}\1\d{4}$")


def is_valid_us_phone_number(
    number: str,
) -> bool:
    """True for ten digits separated uniformly by hyphens, spaces or nothing."""
    return PHONE_PATTERN.match(number) is not None


def digits_only(
    number: str,
) -> str:
    """Drop the separators, leaving the bare ten-digit string."""
    return re.sub(r"[- ]", "", number)


def normalize(
    number: str,
) -> str:
    """Render a valid number in the canonical 123-456-7890 form."""
    if not is_valid_us_phone_number(number):
        raise ValueError(f"not a valid US phone number: {number!r}")
    bare: str = digits_only(number)
    return f"{bare[0:3]}-{bare[3:6]}-{bare[6:10]}"


def area_code(
    number: str,
) -> str:
    """The first three digits of an already validated number."""
    return digits_only(number)[:3]


def classify(
    number: str,
) -> tuple[str, str]:
    """Pair a raw input with a human-readable verdict."""
    if is_valid_us_phone_number(number):
        return number, f"valid -> {normalize(number)} (area {area_code(number)})"
    return number, "invalid"


def validate_all(
    numbers: list[str],
) -> list[tuple[str, str]]:
    """Classify every candidate in the incoming sequence."""
    return [classify(candidate) for candidate in numbers]


def count_valid(
    numbers: list[str],
) -> int:
    """How many of the candidates pass validation."""
    return sum(1 for number in numbers if is_valid_us_phone_number(number))


def format_report(
    numbers: list[str],
) -> str:
    """Build a multi-line report ending with a summary count."""
    width: int = max((len(number) for number in numbers), default=0)
    lines: list[str] = [
        f"{raw.ljust(width)}  {verdict}" for raw, verdict in validate_all(numbers)
    ]
    lines.append(f"{count_valid(numbers)} of {len(numbers)} numbers are valid")
    return "\n".join(lines)


def main() -> None:
    samples: list[str] = [
        "123-456-7890",
        "123 456 7890",
        "1234567890",
        "(123) 456-7890",
        "123-456 7890",
        "123-45-67890",
        "12-3456-7890",
    ]
    print(format_report(samples))


if __name__ == "__main__":
    main()

