        raise ValueError(f"expected two components, got {len(parts)}: {text!r}")
    x, y = (float(p.strip()) for p in parts)
    return (x, y)


def calculate_dot_product(
    vec1: tuple[float, float],
    vec2: tuple[float, float],
) -> float:
    return vec1[0] * vec2[0] + vec1[1] * vec2[1]


def magnitude(
    vec: tuple[float, float],
) -> float:
    return sqrt(calculate_dot_product(vec, vec))


def angle_between(
    vec1: tuple[float, float],
    vec2: tuple[float, float],
) -> float:
    denominator = magnitude(vec1) * magnitude(vec2)
    if denominator == 0.0:
        raise ValueError("angle is undefined for a zero-length vector")
    cosine = calculate_dot_product(vec1, vec2) / denominator
    return degrees(acos(max(-1.0, min(1.0, cosine))))


def classify(
    vec1: tuple[float, float],
    vec2: tuple[float, float],
) -> str:
    product = calculate_dot_product(vec1, vec2)
    if product > 0:
        return "acute"
    if product < 0:
        return "obtuse"
    return "perpendicular"


def format_number(
    value: float,
) -> str:
    if value == int(value):
        return str(int(value))
    return f"{value:.4g}"


def format_vector(
    vec: tuple[float, float],
) -> str:
    return f"({format_number(vec[0])}, {format_number(vec[1])})"


def describe_pair(
    vec1: tuple[float, float],
    vec2: tuple[float, float],
) -> str:
    product = calculate_dot_product(vec1, vec2)
    line = (
        f"{format_vector(vec1)} . {format_vector(vec2)} = "
        f"{format_number(product)} [{classify(vec1, vec2)}]"
    )
    if magnitude(vec1) and magnitude(vec2):
        line += f", angle {format_number(round(angle_between(vec1, vec2), 2))} deg"
    return line


def report(
    pairs: list[tuple[str, str]],
) -> list[str]:
    return [
        describe_pair(parse_vector(left), parse_vector(right))
        for left, right in pairs
    ]


def main() -> int:
    for line in report(
