from __future__ import annotations


def enqueue(
    queue: list,
    item: object,
) -> None:
    queue.append(item)


def dequeue(
    queue: list,
) -> object | None:
    if not queue:
        return None
    return queue.pop(0)


def peek(
    queue: list,
) -> object | None:
    if not queue:
        return None
    return queue[0]


def parse_command(
    line: str,
) -> tuple[str, str | None]:
    parts = line.strip().split(maxsplit=1)
    if len(parts) == 2:
        return (parts[0].lower(), parts[1])
    if parts:
        return (parts[0].lower(), None)
    return ("", None)


def run_command(
    queue: list,
    line: str,
) -> str:
    action, argument = parse_command(line)
    if action == "enqueue":
        if argument is None:
            return "enqueue needs an argument"
        enqueue(queue, argument)
        return "enqueued " + argument
    if action == "dequeue":
        item = dequeue(queue)
        if item is None:
            return "queue empty"
        return "dequeued " + str(item)
    if action == "peek":
        front = peek(queue)
        return "queue empty" if front is None else "front is " + str(front)
    if action == "size":
        return "size is " + str(len(queue))
    return "unknown command: " + action


def format_queue(
    queue: list,
) -> str:
    return "[" + ", ".join(str(item) for item in queue) + "]"


def main() -> None:
    queue = []
    script = ["enqueue alice", "enqueue bob", "peek", "dequeue", "size", "reverse", "dequeue", "dequeue"]
    for line in script:
        print(run_command(queue, line), "->", format_queue(queue))
    print("final queue:", format_queue(queue))


if __name__ == "__main__":
    main()

